import {chromium} from '@playwright/test';
const browser = await chromium.launch({headless:true});
const page = await browser.newPage({viewport:{width:1440,height:1100}});
page.on('pageerror', e => console.log('PAGE ERROR', e.message));
page.on('console', m => {if(m.type()==='error') console.log('CONSOLE ERROR',m.text());});
await page.goto('http://localhost:5175');
await page.waitForTimeout(1500);
console.log(await page.locator('body').innerText());
await page.screenshot({path:'/tmp/cpu-monitor-light.png',fullPage:true});
console.log('chart',await page.locator('.cpu-chart').boundingBox(), 'canvases',await page.locator('canvas').count());
await page.getByRole('button',{name:'Включить тёмную тему'}).click();
await page.waitForTimeout(300);
console.log('dark class',await page.locator('body').getAttribute('class'));
await page.screenshot({path:'/tmp/cpu-monitor-dark.png',fullPage:true});
await browser.close();
JS"

