.yagr-tooltip {
    --yagr-tooltip-font-family:
        'Lucida Grande', 'Lucida Sans Unicode', Arial, Helvetica, sans-serif;

    position: absolute;
    z-index: 1000;
    background-color: #fff;
    border-radius: 4px;
    overflow: hidden;

    font-family: var(--yagr-tooltip-font-family);
    pointer-events: none;

    &__item {
        white-space: nowrap;
        display: flex;
        flex-direction: row;
        justify-content: left;
        align-items: center;
    }

    &__item._active {
        font-weight: bold;
    }

    &_default {
        font-size: 12px;
        padding: 4px 12px;

        box-shadow: 2px 0px 3px rgba(0, 0, 0, 0.1);

        .__title {
            font-size: 14px;
            font-weight: bold;
            margin-bottom: 4px;
        }
        .__section {
            margin-bottom: 4px;
            &:last-child {
                margin: 0;
            }
        }
        .__section_title {
            font-size: 14px;
            font-weight: bold;
            margin-bottom: 2px;
        }
        .__section_scale {
            margin-bottom: 2px;
            background-color: #eee;
            padding: 2px;
        }

        .yagr-tooltip__mark {
            width: 10px;
            height: 10px;
            border-radius: 50%;
            margin-right: 8px;
            display: block;
        }
    }

    &_pinned {
        pointer-events: all;

        ._tooltip-list {
            max-height: 320px;
        }
    }

    ._hidden-rows-number {
        white-space: nowrap;
    }

    &__idx {
        width: 25px;
        white-space: nowrap;
        max-width: 25px;
        overflow: hidden;
    }

    &__tf {
        margin-left: 4px;
    }
}
